     void setup() {                  ― TRIG generates ultrasonic
     pinMode(9, OUTPUT);
     pinMode(10, INPUT);           ― pulseIn() measures echo time
     Serial.begin(9600);           ― Distance calculated using sound
       }
     void loop() {                                  velocity
      digitalWrite(9, LOW);
     delayMicroseconds(2);
      digitalWrite(9, HIGH);
     delayMicroseconds(10);
      digitalWrite(9, LOW);
     duration = pulseIn(10, HIGH);
     distance = duration * 0.034 / 2;
      Serial.print("Distance: ");
      Serial.print("Distance: ");
      Serial.print(distance);
     delay(300);}


