     #define DHTPIN 7                            library
     #define DHTTYPE DHT11
    DHT dht(DHTPIN, DHTTYPE);            – DHTPIN 7 → Data pin connected to pin 7     void setup() {
       Serial.begin(9600);
       dht.begin();                  – dht.readHumidity() → Reads humidity value
       }
     void loop() {                   – dht.readTemperature() → Reads temperature
       float humidity = dht.readHumidity();
       float temperature = dht.readTemperature();                          – Data is printed every 2 seconds
       Serial.print("Humidity: ");
       Serial.print(humidity);
       Serial.print(" % ");
      Serial.print("Temperature: ");
       Serial.print(temperature);
       Serial.println(" °C");
      delay(2000);
       }



